mapper.select:
SELECT , ci.instructor_role AS instructor_role, (SELECT COUNT(*) FROM tb_enrollments e WHERE e.course_id = c.id AND e.status = 'APPROVED') AS enrolled_count, (SELECT i.name FROM tb_institutions i WHERE i.id = c.institution_id) AS institution_name, (SELECT u.name FROM tb_course_instructors mci JOIN tb_users u ON u.id = mci.user_id WHERE mci.course_id = c.id AND mci.instructor_role = 'MAIN' ORDER BY mci.assigned_at ASC LIMIT 1) AS main_instructor_name FROM tb_course_instructors ci JOIN tb_courses c ON c.id = ci.course_id WHERE ci.user_id = #{instructorUserId} AND c.deleted_at IS NULL
AND c.status = #{status}
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*)
  FROM tb_course_instructors ci
  JOIN tb_courses c ON c.id = ci.course_id
 WHERE ci.user_id = #{instructorUserId}
   AND c.deleted_at IS NULL

   AND c.status = #{status}

SELECT , (SELECT COUNT(*) FROM tb_enrollments en WHERE en.course_id = c.id AND en.status = 'APPROVED') AS enrolled_count, (SELECT i.name FROM tb_institutions i WHERE i.id = c.institution_id) AS institution_name, (SELECT u.name FROM tb_course_instructors ci JOIN tb_users u ON u.id = ci.user_id WHERE ci.course_id = c.id AND ci.instructor_role = 'MAIN' ORDER BY ci.assigned_at ASC LIMIT 1) AS main_instructor_name FROM tb_courses c WHERE c.institution_id = #{institutionId} AND c.deleted_at IS NULL
AND c.status = #{status}
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*)
  FROM tb_courses c
 WHERE c.institution_id = #{institutionId}
   AND c.deleted_at IS NULL

   AND c.status = #{status}

SELECT u.id AS user_id, u.name, u.email, u.phone, u.status, r.created_at AS joined_at, r.memo, u.last_login_at, u.birth_date, (SELECT COUNT(*) FROM tb_course_instructors ci JOIN tb_courses c ON c.id = ci.course_id WHERE ci.user_id = u.id AND c.institution_id = #{institutionId} AND c.deleted_at IS NULL) AS course_count FROM tb_user_roles r JOIN tb_users u ON u.id = r.user_id WHERE r.institution_id = #{institutionId} AND r.role = 'INSTRUCTOR'
AND u.status = #{status}
AND ( LOWER(u.name) LIKE '%' || #{keyword} || '%' ESCAPE '\' OR LOWER(u.email) LIKE '%' || #{keyword} || '%' ESCAPE '\' OR REPLACE(u.phone, '-', '') LIKE '%' || REPLACE(#{keyword}, '-', '') || '%' ESCAPE '\' )
ORDER BY
u.name r.created_at
ASC DESC , u.id ASC LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*) FROM tb_user_roles r JOIN tb_users u ON u.id = r.user_id WHERE r.institution_id = #{institutionId} AND r.role = 'INSTRUCTOR'
AND u.status = #{status}
AND ( LOWER(u.name) LIKE '%' || #{keyword} || '%' ESCAPE '\' OR LOWER(u.email) LIKE '%' || #{keyword} || '%' ESCAPE '\' OR REPLACE(u.phone, '-', '') LIKE '%' || REPLACE(#{keyword}, '-', '') || '%' ESCAPE '\' )
